  # Read nodes
  NR == FNR { nodes[$1] = 0; in_d[$1] = 0; out_d[$1] = 0; next }
' <(echo "$nodes") - <(echo "$in_degrees") <(echo "$out_degrees") << 'AWK_SCRIPT'
  # Actually we can do this more simply in a single awk pass over the input file
AWK_SCRIPT

# Let's rewrite the degree calculation to be more efficient
awk -F, '
  {
    out_d[$1]++;
    in_d[$2]++;
    nodes[$1] = 1;
    nodes[$2] = 1;
  }
  END {
    print "node,in_degree,out_degree";
